// CliProfilesService — load/save/list/upsert/delete for the v0.30 multi-
// CLI profiles store. Mirrors LlmChatProfilesService's pattern exactly
// (atomic write, in-memory cache, 0o600 file mode, validation on save).
//
// Storage: ~/.devspace/cli-profiles.json
// Shape:   { profiles: CliProfile[] }
//
// Each CliProfile points a non-Claude CLI runtime ('opencode' for v0.30)
// at an OpenAI-compatible provider config. The matching per-profile
// runtime config dir (e.g. opencode.json under
// ~/.devspace/cli-profiles/<id>/) is generated by the adapter's
// ensureConfig at spawn time — not here. This service ONLY owns the
// profile-list JSON.

import { randomUUID } from 'node:crypto';
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';

import { atomicWriteAsync } from '@main/utils/atomicWrite';
import { assertSafeBaseUrl, isSafeBaseUrl } from '@main/utils/urlSafety';
import { createLogger } from '@shared/logger';
import type { CliId, CliProfile } from '@shared/types';

const logger = createLogger('CliProfiles');

const NAME_CAP = 64;
// API keys cap. OpenCode users may paste larger session tokens (hosted
// LLM gateway proxies emit ~1KB JWTs), so 8KB is plenty of headroom.
const API_KEY_CAP = 8192;
const BASE_URL_CAP = 2048;
const MODEL_CAP = 256;
const SYSTEM_PROMPT_CAP = 4096;
// Reasonable bounds on optional knobs. opencode itself doesn't crash on
// silly values but the renderer slider caps match.
const MIN_CONTEXT_LIMIT = 1024;
const MAX_CONTEXT_LIMIT = 2_000_000;
const MIN_OUTPUT_LIMIT = 16;
const MAX_OUTPUT_LIMIT = 200_000;
// Mode used when persisting credential files. 0o600 = owner read/write
// only; matches the posture LlmChatProfilesService uses.
const SECRET_FILE_MODE = 0o600;
const SECRET_DIR_MODE = 0o700;

// Allowlist of CLI ids that can have a profile. v0.30 only supports
// 'opencode' — 'claude' has no profile (built-in default). Extending
// this in v0.30.x requires both adding the literal here AND wiring the
// matching adapter in registry.ts.
const PROFILE_CLI_IDS: ReadonlyArray<Exclude<CliId, 'claude'>> = ['opencode'];

function profilesFile(): string {
  return path.join(os.homedir(), '.devspace', 'cli-profiles.json');
}

interface ProfilesFileShape {
  profiles: CliProfile[];
}

let cache: CliProfile[] | null = null;

// ─── per-file mutex to defeat read-modify-write races ───────────────────────
//
// upsertProfile/deleteProfile do load → mutate → write; without
// serialization two concurrent IPC calls both read the same baseline and
// the second write clobbers the first. Mirrors McpService.withFileLock.
const writeLocks = new Map<string, Promise<void>>();

async function withFileLock<T>(file: string, fn: () => Promise<T>): Promise<T> {
  const prev = writeLocks.get(file) ?? Promise.resolve();
  let release!: () => void;
  const next = new Promise<void>((resolve) => {
    release = resolve;
  });
  writeLocks.set(file, prev.then(() => next));
  try {
    await prev;
    return await fn();
  } finally {
    release();
    if (writeLocks.get(file) === next) writeLocks.delete(file);
  }
}

function clampNumber(
  v: number | undefined,
  min: number,
  max: number,
): number | undefined {
  if (typeof v !== 'number' || !Number.isFinite(v)) return undefined;
  return Math.max(min, Math.min(max, v));
}

function isAllowedCliId(v: unknown): v is Exclude<CliId, 'claude'> {
  return (
    typeof v === 'string' &&
    (PROFILE_CLI_IDS as ReadonlyArray<string>).includes(v)
  );
}

// Defensive parse — drop anything that doesn't look like a profile so a
// hand-edited / corrupt file can't crash the rest of the service. Like
// LlmChatProfilesService's sanitizeProfile we permit loopback on READ
// (user already configured this profile intentionally) and let the
// upsert path enforce the public-only / public-or-http rules.
// SEC-CRIT-1 fix: reject anything that isn't a UUID on the READ path.
// Profile ids are used to derive `~/.devspace/cli-profiles/<id>/` config
// dirs — a hand-edited file with `"id": "../../.ssh"` would otherwise
// trick the adapter into writing apiKey JSON outside the cli-profiles
// root. Upsert always generates randomUUID()s, so legitimate data
// always passes; only tampered / corrupted entries are quarantined.
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
function isUuid(s: unknown): s is string {
  return typeof s === 'string' && UUID_RE.test(s);
}

function sanitizeProfile(raw: unknown): CliProfile | null {
  if (!raw || typeof raw !== 'object') return null;
  const o = raw as Record<string, unknown>;
  const idStr = typeof o.id === 'string' ? o.id.trim() : '';
  if (!isUuid(idStr)) return null;
  const id = idStr;
  const cliId = o.cliId;
  if (!isAllowedCliId(cliId)) return null;
  const provider = (o.provider ?? {}) as Record<string, unknown>;
  if (!provider || typeof provider !== 'object') return null;
  const modelRaw = typeof provider.model === 'string' ? provider.model.trim() : '';
  if (!modelRaw) return null;
  const name =
    typeof o.name === 'string' && o.name.trim()
      ? o.name.trim().slice(0, NAME_CAP)
      : 'Untitled profile';
  const rawBaseUrl =
    typeof provider.baseURL === 'string'
      ? provider.baseURL.trim().slice(0, BASE_URL_CAP)
      : '';
  // Allow loopback + http on READ — the upsert path is where strict
  // SSRF gating happens.
  const safeBaseUrl =
    rawBaseUrl && isSafeBaseUrl(rawBaseUrl, { allowLoopback: true })
      ? rawBaseUrl
      : '';
  const apiKey =
    typeof provider.apiKey === 'string'
      ? provider.apiKey.trim().slice(0, API_KEY_CAP)
      : '';
  const profile: CliProfile = {
    id,
    name,
    cliId,
    provider: {
      baseURL: safeBaseUrl,
      apiKey,
      model: modelRaw.slice(0, MODEL_CAP),
    },
    createdAt:
      typeof o.createdAt === 'number' && Number.isFinite(o.createdAt)
        ? o.createdAt
        : Date.now(),
  };
  const ctx = clampNumber(
    provider.contextLimit as number | undefined,
    MIN_CONTEXT_LIMIT,
    MAX_CONTEXT_LIMIT,
  );
  if (ctx !== undefined) profile.provider.contextLimit = ctx;
  const out = clampNumber(
    provider.outputLimit as number | undefined,
    MIN_OUTPUT_LIMIT,
    MAX_OUTPUT_LIMIT,
  );
  if (out !== undefined) profile.provider.outputLimit = out;
  if (typeof o.systemPrompt === 'string' && o.systemPrompt.trim()) {
    profile.systemPrompt = o.systemPrompt.slice(0, SYSTEM_PROMPT_CAP);
  }
  return profile;
}

async function readFromDisk(): Promise<CliProfile[]> {
  try {
    const raw = await fs.promises.readFile(profilesFile(), 'utf8');
    const parsed = JSON.parse(raw) as ProfilesFileShape;
    const list = Array.isArray(parsed.profiles) ? parsed.profiles : [];
    const sanitized: CliProfile[] = [];
    for (const p of list) {
      const s = sanitizeProfile(p);
      if (s) sanitized.push(s);
    }
    return sanitized;
  } catch (err) {
    const code = (err as NodeJS.ErrnoException).code;
    if (code !== 'ENOENT') {
      logger.warn(`profiles read failed: ${(err as Error).message}`);
    }
    return [];
  }
}

async function writeToDisk(profiles: CliProfile[]): Promise<void> {
  const payload: ProfilesFileShape = { profiles };
  await atomicWriteAsync(profilesFile(), JSON.stringify(payload, null, 2), {
    mode: SECRET_FILE_MODE,
    dirMode: SECRET_DIR_MODE,
  });
}

function sortByCreated(list: CliProfile[]): CliProfile[] {
  return [...list].sort((a, b) => a.createdAt - b.createdAt);
}

/** Pre-warm cache + return sorted list. Same shape as LlmChatProfilesService. */
export async function loadProfiles(): Promise<CliProfile[]> {
  if (cache) return sortByCreated(cache);
  cache = await readFromDisk();
  return sortByCreated(cache);
}

export async function listProfiles(): Promise<CliProfile[]> {
  return loadProfiles();
}

/**
 * Upsert a profile. New profiles get a UUID + createdAt; existing ones
 * preserve their original createdAt and id.
 *
 * Validation:
 *   - `name` required, trimmed, capped at NAME_CAP (64)
 *   - `cliId` must be 'opencode' (the only allowlist value in v0.30)
 *   - `provider.baseURL` validated via assertSafeBaseUrl with
 *     allowLoopback + allowHttp opt-ins (user-hosted OpenAI-compat
 *     inference servers commonly run plain HTTP on a private network)
 *   - `provider.model` required, trimmed, capped at MODEL_CAP
 *   - `provider.apiKey` trimmed + capped at API_KEY_CAP (may be empty
 *     for not-yet-configured profiles, matching LLM chat profile parity)
 *   - `systemPrompt` capped at 4096 chars; explicit empty string clears
 *   - `provider.contextLimit` / `provider.outputLimit` clamped to
 *     practical bounds
 */
export async function upsertProfile(
  input: Partial<CliProfile>,
): Promise<CliProfile> {
  return withFileLock(profilesFile(), async () => {
  await loadProfiles();
  const list = cache ?? [];

  if (!input || typeof input !== 'object') {
    throw new Error('upsertProfile: invalid payload');
  }

  const trimmedName =
    typeof input.name === 'string' ? input.name.trim() : '';
  if (!trimmedName) {
    throw new Error('upsertProfile: name is required');
  }
  if (!isAllowedCliId(input.cliId)) {
    throw new Error(
      `upsertProfile: cliId must be one of [${PROFILE_CLI_IDS.join(', ')}]`,
    );
  }
  const cliId = input.cliId;

  const provider = (input.provider ?? {}) as Partial<CliProfile['provider']>;
  if (!provider || typeof provider !== 'object') {
    throw new Error('upsertProfile: provider is required');
  }
  const trimmedBaseUrl =
    typeof provider.baseURL === 'string'
      ? provider.baseURL.trim().slice(0, BASE_URL_CAP)
      : '';
  if (!trimmedBaseUrl) {
    throw new Error('upsertProfile: provider.baseURL is required');
  }
  // SSRF gate. Allow loopback for local inference servers and allow
  // plain http for user-hosted endpoints inside a VPN (TLS terminated
  // at the edge). The frontend surfaces a small "no TLS" warning chip
  // when the baseURL is http but doesn't block the save.
  assertSafeBaseUrl(trimmedBaseUrl, { allowLoopback: true, allowHttp: true });

  const trimmedModel =
    typeof provider.model === 'string' ? provider.model.trim() : '';
  if (!trimmedModel) {
    throw new Error('upsertProfile: provider.model is required');
  }
  const trimmedApiKey =
    typeof provider.apiKey === 'string'
      ? provider.apiKey.trim().slice(0, API_KEY_CAP)
      : '';

  const existing =
    typeof input.id === 'string' && input.id.trim()
      ? list.find((p) => p.id === input.id)
      : undefined;

  const next: CliProfile = {
    id: existing?.id ?? randomUUID(),
    name: trimmedName.slice(0, NAME_CAP),
    cliId,
    provider: {
      baseURL: trimmedBaseUrl,
      apiKey: trimmedApiKey,
      model: trimmedModel.slice(0, MODEL_CAP),
    },
    createdAt: existing?.createdAt ?? Date.now(),
  };

  // Optional provider knobs — clamp + preserve through partial updates.
  const ctxIn = clampNumber(
    provider.contextLimit,
    MIN_CONTEXT_LIMIT,
    MAX_CONTEXT_LIMIT,
  );
  if (ctxIn !== undefined) {
    next.provider.contextLimit = ctxIn;
  } else if (existing?.provider.contextLimit !== undefined) {
    next.provider.contextLimit = existing.provider.contextLimit;
  }
  const outIn = clampNumber(
    provider.outputLimit,
    MIN_OUTPUT_LIMIT,
    MAX_OUTPUT_LIMIT,
  );
  if (outIn !== undefined) {
    next.provider.outputLimit = outIn;
  } else if (existing?.provider.outputLimit !== undefined) {
    next.provider.outputLimit = existing.provider.outputLimit;
  }

  // systemPrompt — explicit '' clears, undefined preserves, non-empty
  // string overwrites. Mirrors LlmChatProfilesService semantics.
  if (typeof input.systemPrompt === 'string' && input.systemPrompt.trim()) {
    next.systemPrompt = input.systemPrompt.slice(0, SYSTEM_PROMPT_CAP);
  } else if (
    input.systemPrompt === undefined &&
    existing?.systemPrompt !== undefined
  ) {
    next.systemPrompt = existing.systemPrompt;
  }
  // explicit '' / whitespace -> systemPrompt cleared (next.systemPrompt undefined)

  let updatedList: CliProfile[];
  if (existing) {
    updatedList = list.map((p) => (p.id === existing.id ? next : p));
  } else {
    updatedList = [...list, next];
  }

  await writeToDisk(updatedList);
  cache = updatedList;
  logger.info(
    `upsert profile id=${next.id.slice(0, 8)} cli=${next.cliId} model=${next.provider.model}`,
  );
  return next;
  });
}

/** Idempotent delete. Unknown ids are a no-op. */
export async function deleteProfile(id: string): Promise<void> {
  if (typeof id !== 'string' || !id.trim()) {
    throw new Error('deleteProfile: id is required');
  }
  await withFileLock(profilesFile(), async () => {
    await loadProfiles();
    const list = cache ?? [];
    const next = list.filter((p) => p.id !== id);
    if (next.length === list.length) return;
    await writeToDisk(next);
    cache = next;
    // Arch H6: also remove the per-profile config dir holding the auto-
    // generated opencode.json with the apiKey. Without this the apiKey
    // persists on disk indefinitely after the user thinks they've deleted
    // the profile. Best-effort — log on failure so we still mark the
    // service as having advanced.
    if (isUuid(id)) {
      const dir = path.join(os.homedir(), '.devspace', 'cli-profiles', id);
      try {
        await fs.promises.rm(dir, { recursive: true, force: true });
      } catch (err) {
        logger.warn(`delete profile dir failed: ${(err as Error).message}`);
      }
    }
    logger.info(`delete profile id=${id.slice(0, 8)}`);
  });
}

/** Sync cache lookup — used by hot-path consumers like the OpenCode runner. */
export function getProfile(id: string): CliProfile | undefined {
  if (!cache) return undefined;
  return cache.find((p) => p.id === id);
}

/** Async variant: hydrate the cache before lookup. */
export async function getProfileAsync(
  id: string,
): Promise<CliProfile | undefined> {
  await loadProfiles();
  return cache?.find((p) => p.id === id);
}

/** Best-effort pre-warm so the first chat-panel mount doesn't pay I/O. */
export function preloadProfiles(): void {
  void loadProfiles().catch((err) =>
    logger.warn(`preload failed: ${(err as Error).message}`),
  );
}

/** Testing-only — reset the module cache so each test starts clean. */
export function __resetCacheForTests(): void {
  cache = null;
}
